)

func TestNotClientIPMerged(t *testing.T) {
	input := []byte(`:8080 {
	@webhook {
		path "/webhook"
		not {
			client_ip 51.138.37.238 20.54.89.16
			client_ip 20.50.240.57 40.74.20.78
			client_ip 1.2.3.4
		}
	}
	handle @webhook {
		abort
	}
}`)
	adapter := caddyfile.Adapter{ServerType: caddyhttp.ServerType{}}
	cfg, _, err := adapter.Adapt(input, nil)
	if err != nil {
		t.Fatal(err)
	}
	var out map[string]any
	json.Unmarshal(cfg, &out)
	t.Logf("%s", cfg)
	routes := out["apps"].(map[string]any)["http"].(map[string]any)["servers"].(map[string]any)["srv0"].(map[string]any)["routes"].([]any)
	m := routes[0].(map[string]any)["match"].([]any)[0].(map[string]any)
	not := m["not"].(map[string]any)["matcher_sets_raw"].([]any)[0].(map[string]any)["client_ip"]
	if not == nil {
		t.Fatalf("client_ip missing from not matcher set: %v", m)
	}
	var ipm map[string]any
	json.Unmarshal(not.(json.RawMessage), &ipm)
	ranges := ipm["ranges"].([]any)
	if len(ranges) != 5 {
		t.Fatalf("expected 5 merged ranges, got %v", ranges)
	}
}
EOF
